/**
 * Invoice line-item calculation and breakdown generation (Topological Level 1).
 */

import { apply_tier_discount } from "./discounts";

import { calculate_tax, round_currency } from "./tax_rules";

export function compute_line_total(unit_price: number, quantity: number): number {
  if (((unit_price < 0.0) || (quantity <= 0))) {
    return 0.0;
  }
  return round_currency((unit_price * quantity), 2);
}

export function sum_line_totals(prices: Array<number>): number {
  if ((prices.length === 0)) {
    return 0.0;
  }
  let total = 0.0;
  for (const p of prices) {
    if ((p > 0.0)) {
      total += p;
    }
  }
  return round_currency(total, 2);
}

export function compute_invoice_net_total(prices: Array<number>, tier: string, region: string): number {
  let gross = sum_line_totals(prices);
  let discount = apply_tier_discount(gross, tier);
  let net = round_currency(Math.max(0.0, (gross - discount)), 2);
  let tax = calculate_tax(net, region);
  return round_currency((net + tax), 2);
}
